<script setup>
import { computed, onMounted, ref } from 'vue'
import { assetUrl, gradeLabel, gradeNum, loadIndex, loadPassage, store } from '../../api'
import { soundMap } from '../sound/soundMap'
import './mixLibrary.css'
import { focused, setFocused } from '../../focused.js'
const items=ref([]), loading=ref(true), error=ref(''), search=ref(''), grade=ref('all'), language=ref('all'), audio=ref('all'), bookmarksOnly=ref(false)
const bookmarks=ref(new Set(store.get('mix-bookmarks',[]))), view=ref(store.get('mix-library-view','rows')), selectedId=ref(''), covers=ref({}), maps=ref({}), failed=ref(new Set()), settled=ref(new Set())
const grades=computed(()=>[...new Map(items.value.map(i=>[gradeNum(i.grade),gradeLabel(i.grade)])).entries()].filter(([n])=>n!==null).sort((a,b)=>a[0]-b[0]))
const shown=computed(()=>items.value.filter(i=>(!search.value.trim()||i.title.toLowerCase().includes(search.value.trim().toLowerCase()))&&(grade.value==='all'||gradeNum(i.grade)===Number(grade.value))&&(language.value==='all'||i.lang===language.value)&&(audio.value==='all'||i.voices.includes(audio.value))&&(!bookmarksOnly.value||bookmarks.value.has(i.uuid))).sort((a,b)=>(gradeNum(a.grade)??99)-(gradeNum(b.grade)??99)||a.title.localeCompare(b.title)))
const selected=computed(()=>shown.value.find(i=>i.uuid===selectedId.value)||shown.value[0])
const url=(i,screen='p')=>'#/look/mix/'+screen+'/'+i.uuid
const image=i=>assetUrl('look-art/p-'+i.uuid.slice(0,8)+'-1.webp')
const hasImage=i=>covers.value[i.uuid]&&!failed.value.has(i.uuid)
const rows=i=>maps.value[i.uuid]?.rows.slice(0,4)||[]
const mapLabel=i=>'How the voice moves: '+(maps.value[i.uuid]?.rows.length||0)+' paragraph rows; gaps are pauses'
function setView(v){view.value=v;store.set('mix-library-view',v)}
function toggleBookmark(id){const b=new Set(bookmarks.value);b.has(id)?b.delete(id):b.add(id);bookmarks.value=b;store.set('mix-bookmarks',[...b])}
function clearFilters(){search.value='';grade.value='all';language.value='all';audio.value='all';bookmarksOnly.value=false}
function imageFailed(id){failed.value=new Set([...failed.value,id])}
onMounted(async()=>{document.title='Find a story · Sound Along';try{items.value=await loadIndex();selectedId.value=items.value[0]?.uuid||'';loading.value=false;let cursor=0;async function worker(){while(cursor<items.value.length){const i=items.value[cursor++];try{const d=await loadPassage(i.uuid),root=document.createElement('div');root.innerHTML=d.html||'';const img=root.querySelector('figure img');if(img)covers.value={...covers.value,[i.uuid]:img.alt||'Story illustration'};const map=soundMap(d);if(map)maps.value={...maps.value,[i.uuid]:map}}catch{}finally{settled.value=new Set([...settled.value,i.uuid])}}}await Promise.all([worker(),worker()])}catch{error.value='Could not load the story list.';loading.value=false}})
</script>
<template>
<div class="mix-library"><header class="mix-library-top"><a href="#/look/mix/">ReadWorks <span>Sound Along</span></a><button v-if="focused" type="button" class="mix-all-features" @click="setFocused(false)">All features</button></header><main>
<div class="mix-library-heading"><h1>Find a story</h1></div>
<div class="mix-library-layout"><aside class="mix-library-filters" aria-label="Story filters"><label>Search<input v-model="search" type="search" placeholder="Title"></label><label>Grade<select v-model="grade"><option value="all">All grades</option><option v-for="[n,label] in grades" :key="n" :value="String(n)">{{label}}</option></select></label><details class="mix-library-more"><summary>More</summary><div><label>Language<select v-model="language"><option value="all">All languages</option><option value="EN">English</option><option value="ES">Spanish</option></select></label><label>Audio<select v-model="audio"><option value="all">All audio</option><option value="human">Human voice</option><option value="generated">Generated voice</option></select></label><label class="mix-library-check"><input v-model="bookmarksOnly" type="checkbox"> Bookmarked only</label><button type="button" @click="clearFilters">Clear filters</button><div v-if="!focused" class="mix-library-switch" role="group" aria-label="Library layout"><button type="button" :aria-pressed="view==='rows'" @click="setView('rows')">Rows</button><button type="button" :aria-pressed="view==='bookshelf'" @click="setView('bookshelf')">Bookshelf</button></div></div></details></aside>
<section class="mix-library-results" aria-labelledby="mix-results"><div class="mix-library-results-head"><div><h2 id="mix-results">Stories</h2><p aria-live="polite">{{shown.length}} {{shown.length===1?'result':'results'}}</p></div></div><p v-if="loading" role="status">Loading stories…</p><p v-else-if="error" role="alert">{{error}}</p><p v-else-if="!shown.length">No stories match these filters. <button type="button" @click="clearFilters">Show all stories</button></p>
<div v-else-if="view==='rows' || focused" class="mix-library-list"><article v-for="i in shown" :key="i.uuid" class="mix-library-row"><div class="mix-library-cover"><img v-if="hasImage(i)" :src="image(i)" :alt="covers[i.uuid]" loading="lazy" @error="imageFailed(i.uuid)"><div v-else class="mix-library-image-fallback" role="img" :aria-label="covers[i.uuid]||'Story illustration'"><svg viewBox="0 0 80 60" aria-hidden="true"><path d="M5 50 27 26l13 11 12-17 23 30Z"/><circle cx="24" cy="17" r="5"/></svg></div></div><div class="mix-library-row-body"><h3><a :href="url(i)">{{i.title}}</a></h3><p>{{gradeLabel(i.grade)}} · {{i.lexile?i.lexile+'L':'Lexile not listed'}} · {{i.words}} words <template v-if="i.lang==='ES'">· Spanish</template></p><div v-if="!focused" class="mix-library-map-space"><svg v-if="rows(i).length" class="mix-library-map" :viewBox="'0 0 300 '+rows(i).length*12" role="img" :aria-label="mapLabel(i)"><g v-for="(row,ri) in rows(i)" :key="ri" :transform="'translate(0 '+ri*12+')'"><rect v-for="(bar,bi) in row" :key="bi" :x="bar.x" y="2" :width="bar.w" height="6" rx="2"/></g></svg><span v-else-if="!settled.has(i.uuid)">Opening voice shape…</span><span v-else>Voice shape unavailable</span></div><div class="mix-library-actions"><a v-if="i.lang!=='ES'" :href="url(i,'kid')">Younger readers →</a></div></div><button class="mix-library-bookmark" type="button" :aria-label="(bookmarks.has(i.uuid)?'Remove bookmark for ':'Bookmark ')+i.title" :aria-pressed="bookmarks.has(i.uuid)" @click="toggleBookmark(i.uuid)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v18l-7-5-7 5z" :fill="bookmarks.has(i.uuid)?'currentColor':'none'"/></svg></button></article></div>
<div v-else class="mix-library-shelf-layout"><div class="mix-library-shelves" aria-label="Story bookshelf"><div v-for="group in Math.ceil(shown.length/6)" :key="group" class="mix-library-shelf"><button v-for="(i,bi) in shown.slice((group-1)*6,group*6)" :key="i.uuid" type="button" class="mix-library-spine" :class="['mix-library-spine-'+(((group-1)*6+bi)%5),{'mix-library-picked':selected?.uuid===i.uuid}]" :aria-label="'Open '+i.title" :aria-pressed="selected?.uuid===i.uuid" @click="selectedId=i.uuid"><span>{{i.title}}</span></button></div></div><article v-if="selected" class="mix-library-preview" aria-live="polite"><div class="mix-library-preview-art"><img v-if="hasImage(selected)" :src="image(selected)" :alt="covers[selected.uuid]" @error="imageFailed(selected.uuid)"><div v-else class="mix-library-image-fallback" role="img" :aria-label="covers[selected.uuid]||'Story illustration'"><svg viewBox="0 0 80 60" aria-hidden="true"><path d="M5 50 27 26l13 11 12-17 23 30Z"/><circle cx="24" cy="17" r="5"/></svg></div></div><h3>{{selected.title}}</h3><p>{{gradeLabel(selected.grade)}} · {{selected.words}} words</p><div class="mix-library-map-space"><svg v-if="rows(selected).length" class="mix-library-map" :viewBox="'0 0 300 '+rows(selected).length*12" role="img" :aria-label="mapLabel(selected)"><g v-for="(row,ri) in rows(selected)" :key="ri" :transform="'translate(0 '+ri*12+')'"><rect v-for="(bar,bi) in row" :key="bi" :x="bar.x" y="2" :width="bar.w" height="6" rx="2"/></g></svg><span v-else-if="!settled.has(selected.uuid)">Opening voice shape…</span><span v-else>Voice shape unavailable</span></div><div class="mix-library-actions"><a :href="url(selected)">Read and listen →</a><a v-if="selected.lang!=='ES'" :href="url(selected,'kid')">Kid view →</a></div></article></div>
</section></div></main></div>
</template>
